 const roles=actorRoles(actor);const name=(id?:string)=>actor.employees.find(e=>e.id===id)?.name||'Not assigned';
 const [owner,setOwner]=useState(a.owner),[start,setStart]=useState(a.start),[due,setDue]=useState(a.due),[conditions,setConditions]=useState(a.conditions),[instructions,setInstructions]=useState(a.notes),[progress,setProgress]=useState(a.progressNotes||''),[target,setTarget]=useState(''),[comments,setComments]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
