 const header=focused&&<TaskHeader eyebrow={(a.owner===actor.id?'YOUR TASK':planner?'YOUR TEAM’S TASK':'TASK')+' · '+a.stream+(a.kind==='validation'?' · VALIDATION':'')+(ext?' · EXTERNAL':'')} title={a.title} jobNumber={job.jobNumber} sample={a.sampleId+' · '+(sample?containerLabel(sample):'container not recorded')} status={ext?externalStage(a):labStatus(a)} statusTone={'lab-'+labStatus(a).toLowerCase().replace(/[^a-z]+/g,'-')} due={a.due} dueLabel="Test due" next={yourNext} action={mainLabel?<button type="button" className="primary-button" onClick={toAction}>{mainLabel}</button>:undefined}/>;
